\begin{tikzpicture}[font=\sffamily, line width=0.8pt]
% solutions
\fill[gray!20] (0.5,0.03) rectangle (3.5,2.2);
\fill[gray!20] (5.5,0.03) rectangle (8.5,2.2);
\draw (0.5,3) -- (0.5,0) -- (3.5,0) -- (3.5,3);
\draw (5.5,3) -- (5.5,0) -- (8.5,0) -- (8.5,3);
\draw (0.5,2.2) -- (3.5,2.2);
\draw (5.5,2.2) -- (8.5,2.2);
% electrodes
\filldraw[fill=gray!70] (1.4,0.4) rectangle (1.8,3.6);
\filldraw[fill=gray!40] (6.8,0.4) rectangle (7.2,3.6);
% salt bridge (tube)
\draw[line width=3.5pt, gray!60, line cap=butt] (2.7,1.4) -- (2.7,3.3) -- (5.8,3.3) -- (5.8,1.4);
\draw[line width=1.4pt, white, line cap=butt] (2.7,1.4) -- (2.7,3.3) -- (5.8,3.3) -- (5.8,1.4);
% wires and voltmeter
\draw (1.6,3.6) -- (1.6,5.2) -- (3.7,5.2);
\draw (7.0,3.6) -- (7.0,5.2) -- (5.3,5.2);
\draw[fill=white] (4.5,5.2) circle (0.5) node {V};
% labels
\draw (1.0,1.2) -- (1.4,1.2);
\node[anchor=east] at (0.95,1.2) {zinc};
\draw (7.2,1.2) -- (7.65,1.2);
\node[anchor=west] at (7.7,1.2) {copper};
\node[anchor=west] at (4.1,2.5) {salt bridge};
\draw[-{Stealth[length=2mm]}, line width=0.5pt] (4.15,2.7) -- (4.15,3.2);
\node[align=center] at (2.0,-0.9) {ZnSO$_4$(aq)\\1.0 mol dm$^{-3}$};
\node[align=center] at (7.0,-0.9) {CuSO$_4$(aq)\\1.0 mol dm$^{-3}$};
\node at (4.5,-2.1) {Fig. 6.1};
\end{tikzpicture}

